API=${API:-http://localhost:8001}
login() { C=$(curl -s $API/api/auth/captcha); CID=$(echo $C | python3 -c "import sys,json;print(json.load(sys.stdin)['id'])"); ANS=$(echo $C | python3 -c "import sys,json;q=json.load(sys.stdin)['question'].split();print(int(q[0])+int(q[2]))"); curl -s -X POST $API/api/auth/login -H 'Content-Type: application/json' -d "{\"username\":\"$1\",\"password\":\"maiharta123\",\"captcha_id\":\"$CID\",\"captcha_answer\":\"$ANS\"}" | python3 -c "import sys,json;print(json.load(sys.stdin)['token'])"; }
